content.text:
The root cause is a single fault: the `search` service crash-looped and never came back during the abnormal window. Its failure reaches users through `frontend`'s `/hotels` endpoint.

```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'spans_ab' src, count(*) n, CAST(min(time) AS VARCHAR) t0, CAST(max(time) AS VARCHAR) t1 FROM abnormal_traces WHERE service_name='search' UNION ALL SELECT 'spans_no', count(*), CAST(min(time) AS VARCHAR), CAST(max(time) AS VARCHAR) FROM normal_traces WHERE service_name='search'",
          "claim": "search emitted 1950 spans in the normal window and zero spans in the abnormal window."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, attr_k8s_pod_name pod, CAST(min(time) AS VARCHAR) t0, CAST(max(time) AS VARCHAR) t1, min(value) v_min, max(value) v_max FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND service_name='search' GROUP BY ALL",
          "claim": "search pod restart counter rises from 3 to 6 during the abnormal window; it was 0 in normal."
        },
        {
          "kind": "log",
          "sql": "SELECT regexp_extract(message, '\"reason\":\"([^\"]+)\"', 1) reason, regexp_extract(message, '\"name\":\"([^\"]+)\"', 1) obj, count(*) n, CAST(min(time) AS VARCHAR) t0, CAST(max(time) AS VARCHAR) t1 FROM abnormal_logs GROUP BY ALL ORDER BY 3 DESC",
          "claim": "Kubernetes events show search-77745d5c76-fq4hb repeatedly Killed, Failed and in BackOff until the end of the window."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, attr_status_code, count(*) n, avg(duration)/1e6 avg_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='search.Search/Nearby' GROUP BY ALL",
          "claim": "Frontend's client calls to search.Search/Nearby all return Error status, 673 of them, with no successful calls."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_http_response_status_code code, attr_status_code st, count(*) n, avg(duration)/1e6 avg_ms FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND span_name='HTTP /hotels' GROUP BY ALL",
          "claim": "Frontend's HTTP /hotels server spans return 500 Error in 673 of 678 requests, failing fast at about 0.2 ms, versus 0 errors normally."
        }
      ]
    }
  ]
}
```

